ProjectALife.DialogueShards["radio_1"] = {
{"exp_dispatch_pencil","scanner",0,5,0,23,1,{"Dispatch","Who took the pencil from the incident board?","Unit Seven","We have larger problems than a pencil","Dispatch","Yes, and I am trying to write those down","Unit Seven","There's a pen beside the telephone","Dispatch","That one stopped working before lunch","Unit Seven","Check under the yellow pad","Dispatch","Found it - thank you - now, which call were you answering?","Unit Seven","That's what I was calling to find out"}},
{"exp_guard_letters","military",0,10,0,23,1,{"Supply","The names on this list don't match the names on the boxes","Corporal","Check the second sheet, first one's yesterday","Supply","Second sheet says to use the first sheet","Corporal","Naturally it does - who signed it?","Supply","Can't read the signature, could be anybody","Corporal","Put both sheets aside, tell me what is physically in front of you","Supply","Boxes, Corporal, with the wrong names","Corporal","Alright, we have established that the boxes exist"}},
{"exp_checkpoint_map","military",0,5,0,23,1,{"Private","I've got three copies of the map and different markings on each","Sergeant","Check the dates in the corners","Private","Same date on all three, Sergeant","Sergeant","Who gave them to you?","Private","Three different people, each said theirs was current","Sergeant","Do not send anyone down a road based on those markings","Private","Then what do I tell the people asking?","Sergeant","That we're checking, it's the truth, even when it sounds bad"}},
{"exp_radio_not_switchboard","host",0,14,0,23,1,{"June","Someone asked me to connect them to the county office","June","I don't have that kind of connection, this isn't a switchboard","June","There isn't a roomful of people behind me taking messages","June","There's a chair that squeaks, and me","June","I ought to have explained that sooner, a steady voice can give the wrong impression","June","If I don't answer immediately, I'm probably trying to hear the last caller","June","Please don't mistake an unanswered call for a refusal to care","June","And if you hear squeaking, that's the chair, not a distress code"}},
{"more_radio_first_locked_door","caller_story_horror",0,7,21,5,1,{"Anne","I locked a door on somebody today","Anne","I knew them, before anyone asks, I knew them","Anne","They weren't... they couldn't talk anymore, just that noise","Anne","But I keep thinking they'll say my name - ask why I locked it","June","Are you away from that door now?","Anne","Yes, I'm somewhere else","June","Okay, sorry, I thought you meant they were there with you","Anne","I can hear them in my head - not here, I know the difference","June","I believe you","Anne","Thank you, everybody keeps telling me to check the door again"}},
{"more_radio_empty_car_seat","caller_story_horror",0,10,20,5,1,{"Unknown","There was a child's seat in the car","Unknown","Empty, I want to say that first, it was empty","Unknown","I looked for somebody around it until my friend pulled me away","Unknown","I didn't see a child, I didn't see anybody who could tell me","June","You don't know what happened","Unknown","No, I know I don't - doesn't stop me thinking about it, though","Unknown","All I saw was a seat, I keep having to tell myself that","Unknown","Maybe somebody carried them","June","Maybe they did","Unknown","Yeah, maybe, sorry, that's all I've got, I don't know anything else"}},
{"more_radio_first_time_praying","caller_story_sad",0,10,21,5,1,{"Leon","I tried praying and couldn't remember how it started","Leon","'Dear...' And I stopped - dear? Is that a letter? Ah, shit - see? I'm doing it again","June","What did you say?","Leon","Please, a lot of times","Leon","Just 'please.' Over and over, ran out of anything else","Leon","My grandma would know the proper words","June","What would she say to you forgetting them?","Leon","Probably pat my hand and tell me to try again","Leon","She'd say, 'Slow down, Leon, he can hear you'","Leon","Sorry, didn't think saying that out loud would get to me"}},
{"more_radio_no_cure_rumor","instruction",0,30,0,23,1,{"June","Someone asked me to repeat a story about a cure","June","I asked who had seen it work, they couldn't tell me","June","I am not broadcasting the directions that came with that story","Caller","What if it's real?","June","Then I need more than 'my cousin heard it.' I'm sorry, but I do","Caller","People need hope","June","I know - I KNOW - but if someone drives out there because I said it on the radio?","Caller","You're saying you don't know","June","Yes, plainly - I don't know","June","I wish I had something better, I really do - I can't give you those directions"}},
{"more_radio_wrong_shoes","caller_story_sad",0,7,0,23,1,{"Anne","I left in the wrong shoes","June","Can you walk in them?","Anne","Yes, no, I mean-- one's brown, the other's black","Anne","They don't even look alike, I don't know how I did that","June","You were rushing, weren't you?","Anne","I... yes, I must've been - I keep looking down at them","Anne","I remembered to lock the back door - can you believe that?","June","I can","Anne","Locked the door, left with two different shoes","June","I'm glad you called, Anne, even about shoes"}},
{"more_radio_dispatch_spell","scanner",0,5,0,23,1,{"Dispatch","Repeat the caller's surname","Unit Seven","He wouldn't give one","Dispatch","I need something for the form","Unit Seven","Nothing I can put on the form, Dispatch, he's still yelling","Dispatch","Use unknown","Unit Seven","Already did, that's what started the argument","Dispatch","What does he want?","Unit Seven","To know when everything goes back to normal","Dispatch","I haven't got an answer for him - does he need medical?","Unit Seven","Negative - just scared, I'll talk to him"}},
{"more_radio_deputy_pen","scanner",0,7,0,23,1,{"Deputy","Control, do we have spare pens?","Control","Pens?","Deputy","I'm writing names on my arm and this one's dying","Control","Why your arm?","Deputy","Gave my notebook to a woman making a list, forgot to get it back","Control","How many names?","Deputy","Enough that I need the other sleeve rolled up","Control","Missing people?","Deputy","People somebody's looking for","Control","I'll find a pen"}},
{"more_radio_recruit_tent","military_mistake",0,10,0,23,1,{"Private","Sergeant, this tent's got a piece missing","Sergeant","What piece?","Private","The piece that makes it stay up","Sergeant","That would be you, Private","Private","Very funny, Sergeant","Sergeant","Check the pole sleeve","Private","Oh, uh...","Private","Found it - don't-- don't come over here","Sergeant","You threaded it through the wrong side, didn't you?","Private","It's up now, Sergeant - can we leave it at that?"}},
{"king_radio_no_diagnosis","instruction",0,3650,0,23,1,{"June","We can't tell you what a wound is over this channel","June","I know that isn't the answer you want","June","Please don't let somebody make a diagnosis because they sound confident","June","Tell anyone helping you what actually happened","June","If you don't know, say so","June","There's no shame in being frightened","June","And being quiet doesn't mean it doesn't hurt","June","Give each other time to answer"}},
{"knox_first_mic","sign_on",0,2,0,23,1,{"June","Hello? If that squeal came through, I'm sorry, the microphone was too close to the speaker","June","My name's June, this isn't an official station - I'm a person with a working transmitter","June","I can pass on what people say, I can't make it true just by saying it louder","June","If you call in, tell us what you saw yourself - please keep guesses separate"}},
{"knox_number_wrong","host",0,3,0,23,1,{"June","Someone asked whether this was the emergency service - no - I'm sorry","June","I can't dispatch a car or an ambulance, I don't want anyone waiting for one because they heard my voice","June","What I can do is leave some space for someone else to answer","June","If you know more than I do, this is a very good time to speak"}},
{"knox_shopping_note","caller_story_sad",0,7,0,23,1,{"Earl","I found my wife's grocery list in my pocket, milk, eggs, dishwasher soap","June","Little things can hit pretty hard","Earl","She put a line under the soap twice, I forgot it last time","Earl","I keep thinking about how nice it would be to get fussed at for that again"}},
{"knox_officer_repeat","scanner",0,3,0,23,1,{"Unit Twelve","Dispatch, repeat the last instruction, I heard two different destinations","Dispatch","Twelve, stand by for clarification","Unit Twelve","I've been standing by, people keep asking where they're supposed to go","Dispatch","I understand, I don't have a confirmed answer to give you yet"}},
{"knox_school_question","caller_story_sad",0,7,0,23,1,{"Marie","My little boy asked if he still had to finish his summer reading","June","What did you tell him?","Marie","I said we'd read a chapter together, I didn't know what else to say","Marie","He complained about it, best sound I heard all day"}},
{"knox_over_button","military_mistake",0,7,0,23,1,{"Private","Sergeant, is the button down when you're listening or when you're talking?","Sergeant","You're transmitting that question","Private","Right, sorry, Sergeant - out","Sergeant","Let go of the button, son"}},
{"knox_false_convoy","instruction",0,14,0,23,1,{"June","Please stop repeating that a convoy is coming as if we've confirmed one","June","I heard the same story you did, hearing it twice doesn't make two sources","June","This station has no verified pickup time or place","June","If that changes, I'll say how we know, until then, don't pack your life around a rumor"}},
{"knox_open_mic_fear","military",0,7,0,23,1,{"Private","I thought there'd be a proper briefing","Corporal","There was, nobody knew enough to fill it","Private","Does that make you feel better?","Corporal","No, and your radio's open again"}},
{"knox_weather_honesty","weather",0,3650,0,23,1,{"June","For the person requesting a weather forecast, I'm afraid you're asking a woman with a window","June","I don't have a countywide forecast to read","June","The view from here wouldn't tell me what's happening where you are","June","That's your weather report, short, disappointing, and at least not invented"}},
{"knox_caller_bad_signal","host",0,3650,0,23,1,{"June","To the caller who kept fading out, I couldn't make out your message","June","Please don't take my silence as an answer","June","I won't guess at a location or a name and send someone the wrong way","June","If you can try again, go slowly"}},
{"knox_goodnight_early","sign_off",0,7,20,4,1,{"June","I need to step away from the microphone","June","This isn't an official end to anything, just one tired person needing a rest","June","I don't know when I'll be back on - please don't wait on me to make your decisions","June","If you heard another human voice tonight, at least we managed that"}},
{"r1_d0_shift_briefing_oddities","scanner",0,0,15,17,2,{"Knox 20","Knox 20 to all night shift units, before day shift goes home, a couple things from today","Knox 20","Three assault calls since noon where the suspect bit the victim - three, none of them knew each other","Knox 20","Day shift says every one of those suspects was running a fever and none of them would say a word - not even their name","Knox 11","Knox 11, Sarge, full moon tonight?","Knox 20","Moon's got nothing to do with it, gloves on, keep your distance, and don't let anybody get their mouth near your hands","Knox 4","Knox 4 copies, worst thing that ever bit me on this job was a Pomeranian","Knox 20","Then you've had it easy, Knox 4, night shift is 10-8 - good luck, everybody"}},
{"r1_d0_heat_gown_lookout","scanner",0,0,14,19,1,{"Dispatch","All Knox units, the heat advisory is in effect through Sunday - check on your elderly calls, and drink something yourselves","Knox 11","Knox 11 copies, the air in my car quit at noon, so I'm drinking plenty","Dispatch","Also, attention all units - Knox County Hospital requests a lookout for a patient who walked out of the emergency room about thirty minutes ago","Dispatch","White male, sixties, wearing a hospital gown and one sock - hospital states he may be combative, last seen walking toward the back parking lot","Knox 4","Knox 4, dispatch, what's he being treated for?","Dispatch","They wouldn't say over the phone, the charge nurse just said do not let him bite anybody","Knox 4","Say again that last part?","Dispatch","You heard it right, Knox 4, those were her exact words"}},
{"r1_d0_adam14_bedroom_door","scanner",0,0,16,23,2,{"Louisville Radio","2-Adam-14, domestic in progress, 4410 Greenwood Road, apartment 6, caller states her husband bit her and is trying to get through the bedroom door","2-Adam-14","2-Adam-14, show me en route from Dixie and Crums Lane","Louisville Radio","Adam-14, be advised the caller says he's been sick since last night with a fever, and he isn't talking - just making noise","2-Adam-14","Copy - any weapons in the house?","Louisville Radio","Negative weapons, she says she hit him with a lamp and he didn't react to it","2-Adam-14","Start me a second car, and have EMS stage at the corner","2-Adam-13","2-Adam-13, I'll back him, about four minutes","2-Adam-14","Adam-14 on scene, I can hear it from the parking lot","Louisville Radio","Copy, on scene at {time}, caller's still on the line, she's in the bedroom closet with her daughter","2-Adam-14","Tell her stay put, we're going up to the door now"}},
{"r1_d0_muldraugh3_pool_table","scanner",0,0,21,2,1,{"Muldraugh 3","Muldraugh 3, I'm out at the tavern on 31W, one subject fighting in the lot","Dispatch","Copy, Muldraugh 3, nearest county unit is Knox 11, about eight minutes out","Muldraugh 3","Start him - Subject's bleeding from the mouth and he's not listening to anybody","Muldraugh 3","I gave him a full shot of OC, right in the face - nothing, he didn't even blink","Dispatch","Muldraugh 3, confirm the subject is still on his feet?","Muldraugh 3","Still on his feet, still coming, the bouncer's got him pinned under a pool table they dragged out into the lot","Knox 11","Knox 11, I'm going Code 3","Muldraugh 3","He's biting at the table legs, I don't want to go hands-on with this one","Dispatch","Understood - wait for your backup - EMS is staging at the truck stop","Muldraugh 3","Tell EMS to bring the leather restraints - both sets"}},
{"r1_d0_medic3_overpass_code","scanner",0,0,17,23,2,{"Dispatch","Medic 3, Knox 7, 10-50 with injuries, 31W southbound at the Route 1638 overpass - single vehicle into the guardrail","Knox 7","Knox 7, 10-23, one occupant, male, not breathing - no skid marks, looks like he was gone before he ever hit the rail","Medic 3","Medic 3 on scene, dispatch, show us working a code, no pulse, no respirations","Medic 3","Dispatch, Medic 3, I need law at the back of my unit right now! Patient is combative!","Dispatch","Medic 3, say again, I show your patient in cardiac arrest","Medic 3","He was! He got up off the cot and he's got my partner's arm!","Knox 7","Knox 7, I'm right here, going to the back doors","Dispatch","All units hold your traffic - Knox 7, advise when able","Knox 7","Dispatch, send a second ambulance, paramedic is bit on the forearm - the patient's strapped down now","Dispatch","Second ambulance en route - Knox 7, are you injured?","Knox 7","He got my sleeve, barely broke the skin - I'm fine"}},
{"r1_d0_knox7_argues","scanner",0,0,21,3,1,{"Knox 20","Knox 20 to Knox 7","Knox 7","Go ahead, Sarge","Knox 20","EMS supervisor tells me you took a bite on that wreck - go get it looked at, that isn't a request","Knox 7","Sarge, it's a scratch, I've had worse off a cat","Knox 20","Then it'll be a real short visit - go to the hospital","Knox 7","I drove past there twenty minutes ago, cars parked on the grass, people sitting on the curb bleeding - I'd be in that waiting room till Tuesday","Knox 20","Then go home, scrub it with soap and peroxide, and go 10-7 for the night","Knox 7","We're down to six cars, Sarge","Knox 20","And now we'll be down to five - Knox 7, go home","Knox 7","10-4 - Knox 7 is 10-7 at my residence - put it in the log that I argued","Dispatch","It's in the log, Knox 7 - rest up"}},
{"r1_d0_pruitt_lane_bathroom","scanner",0,0,0,4,2,{"Dispatch","Knox 9, Knox 15, priority call. 212 Pruitt Lane, March Ridge - female caller locked in the upstairs bathroom, someone inside the residence","Knox 9","Knox 9 en route from the bypass, Code 3","Knox 15","Knox 15, I'm coming from West Point, I'm a ways","Dispatch","The caller is whispering, she says the person in the house is her father","Dispatch","She says her father had a heart attack at the supper table - the family's been waiting on the funeral home since seven","Knox 9","Dispatch, Knox 9, say again? Her father is deceased?","Dispatch","That's what she's telling me, Knox 9, she says he's out in the hall scratching at the bottom of the door","Knox 9","Tell her not to open that door for anything, not for any voice, until somebody says the name Deputy Ames","Dispatch","I'm telling her - deputy Ames, she repeated it back to me","Knox 9","Knox 9 on scene, front door's standing open - I'm going in","Dispatch","All units, hold your traffic for Knox 9"}},
{"r1_d0_riverside_garage_roof","scanner",0,0,20,1,1,{"Riverside 1","Riverside 1, show me out on the juvenile complaint, Elm and Fourth - party in a backyard","Dispatch","Copy, Riverside 1, the neighbor says the kids are screaming, and not the party kind","Riverside 1","I've got four juveniles up on a garage roof, they pulled the ladder up after them","Riverside 1","They're saying their buddy is in the yard and he went after one of the girls with his teeth - stand by","Riverside 1","I've got eyes on him, male, about seventeen, over by the grill - his head's hanging wrong and he's still walking","Dispatch","Riverside 1, do you need a second unit?","Riverside 1","Every unit you've got, and tell the parents on the phone those kids stay on that roof","Dispatch","Nearest is Knox 11 and he's tied up in Muldraugh - I've got nobody else, Riverside","Riverside 1","Then I'm staying in the car with the lights going - he's watching the light bar - good - keep looking at me, buddy"}},
{"r1_d0_westpoint_beer_cooler","scanner",0,0,18,2,1,{"West Point 2","West Point 2, 10-23 at the all-night gas station on Main Street, on the robbery call","West Point 2","No robbery, clerk says a customer bit her over a pack of cigarettes","Dispatch","Copy - is the suspect still on scene?","West Point 2","Affirmative, the clerk lured him into the walk-in beer cooler and ran a mop handle through the door pulls","West Point 2","He's in there throwing himself at the glass, knocking down a case of beer every time","Dispatch","Do you need EMS for the clerk?","West Point 2","She's refusing, says she's finishing her shift, and she wants it on record that he never paid for the cigarettes","Dispatch","It's on the record, West Point 2","West Point 2","I'm leaving him in the cooler till I get a second car - he's not going anywhere, and it's the coldest spot in town"}},
{"r1_d0_tobacco_field_porch","scanner",0,0,21,1,1,{"Dispatch","Knox 4, shots fired complaint, Fairview Church Road - Multiple callers","Knox 4","Knox 4 en route, it's the Friday after the Fourth, dispatch - I'll bet you a dollar it's bottle rockets","Dispatch","No bet, the caller says she can tell fireworks from a deer rifle","Knox 4","Knox 4 on scene, I owe you a dollar","Knox 4","Man on the porch with a thirty-thirty, says there's people standing in his tobacco and they won't answer him","Dispatch","Is he cooperative?","Knox 4","Cooperative, he leaned the rifle on the rail - wants me to go have a look","Knox 4","My spotlight's on the field, there's six of them standing in the rows - they're all looking at his porch light","Dispatch","Knox 4, do not walk that field alone","Knox 4","Wasn't planning on it, I'm going to sit on the porch with the man a while - he's putting coffee on"}},
{"r1_d0_trooper422_charter_bus","scanner",0,0,19,4,2,{"Trooper 422","Post 4, 422","Post 4","422, go ahead","Trooper 422","10-97 at the southbound rest area on I-65, charter bus parked across three spaces, engine running, no driver","Trooper 422","The windows are fogged up, there's people inside hitting the glass, twenty, maybe more","Post 4","Copy - can you make contact through the door?","Trooper 422","Negative, they don't talk - they just hit the glass harder when I get close","Trooper 422","The driver's jacket is on the pavement by the door - there's blood on the step","Post 4","422, sergeant advises do not open that bus - hold the scene for a second unit","Trooper 422","Copy - Tennessee plates, church group lettering on the side, somebody's going to be calling about these folks","Post 4","We'll run it - stay in your car, 422"}},
{"r1_d0_k9_bo_quits","scanner",0,0,19,3,1,{"Dispatch","Knox 12, can you respond with your K-9 to Pine Hollow Road? Subject fled into the woods after assaulting a family member","Knox 12","Knox 12, en route with Bo","Knox 12","Knox 12 on scene, track started off the back porch - he's got it","Knox 12","Dispatch, Knox 12 - Bo quit about fifty yards into the trees","Dispatch","Lost the scent?","Knox 12","No, he's got the scent, he won't go - he's backing into my legs and whining","Knox 12","Six years this dog's gone in after armed men without making a sound - he's shaking","Dispatch","Knox 12, disregard the track, return to your unit","Knox 12","Already walking back, he's pulling me to the car"}},
{"r1_d0_medic2_loading_dock","scanner",0,0,18,4,1,{"Medic 2","Knox County Hospital, Medic 2 with a report","Hospital","Go ahead, Medic 2","Medic 2","Forty-two-year-old male, bite wound to the left forearm about four hours old - Temp one-oh-four point six, pulse one-forty, unresponsive to pain","Medic 2","We're about twelve minutes out, requesting a room","Hospital","Medic 2, be advised we are on total diversion - take your patient to Louisville","Medic 2","Louisville is on diversion, every emergency room up there, we called them all","Hospital","Stand by, Medic 2","Hospital","Medic 2, bring him in - go around back to the loading dock, not the ambulance bay - somebody will meet you","Medic 2","Loading dock, copy - why the dock?","Hospital","Because the bay is full, Medic 2 - twelve minutes"}},
{"r1_d0_holding_fourteen","scanner",0,0,22,3,2,{"Dispatch","All Knox units, be advised I'm holding fourteen calls, if anybody comes clear, let me know","Knox 4","Knox 4, still on Fairview Church Road","Knox 9","Knox 9, still at Pruitt Lane, I need the coroner out here, and EMS for the daughter's hand","Knox 11","Knox 11, transporting one to the jail","Knox 15","Knox 15, standing by with the family at Coyle Road","Knox 12","Knox 12, I'm clear - give me the oldest one you've got","Dispatch","Knox 12, the oldest is an alarm at the elementary school - it tripped at 9:40 and it hasn't stopped","Knox 12","Somebody inside a school in July?","Dispatch","The caller says the janitor's truck is still in the lot","Knox 12","En route","Dispatch","The rest of you, when you come clear, the next four are all the same call - somebody in a house who won't come out and won't stop banging"}},
{"r1_d0_school_gym_padlock","scanner",0,0,23,4,1,{"Knox 12","Knox 12, 10-23 at the elementary school, janitor's truck is here, keys in the ignition","Knox 12","I can see him through the gym door glass, he's walking into the motion sensor over and over, that's the alarm","Dispatch","Is he injured?","Knox 12","His shirt's soaked dark down one side, he walked into the door when he saw my flashlight and he just keeps walking into it","Knox 12","Dispatch, the gym has chain doors, I've got a padlock in my trunk - I'm locking him in","Dispatch","Knox 12, you want to confirm that? You're securing the subject inside the building?","Knox 12","Affirmative, nobody's in that school till Monday - put a note in for the principal and the school board both","Dispatch","Noted - what do you want me to tell the alarm company?","Knox 12","Tell them it's a false alarm, it'll make their night"}},
{"r1_d0_ems9_driverless","scanner",0,0,20,2,1,{"Louisville Radio","All cars, all districts - EMS unit 9 left Southwest General without a driver cleared to take it - last seen northbound Dixie Highway at Greenwood","4-Boy-22","4-Boy-22, I've got it, northbound Dixie at Crums Lane, lights going, weaving across the center line","Louisville Radio","4-Boy-22, the EMS supervisor says the crew and a patient may be inside","4-Boy-22","Copy, it won't stop for my lights - it's only doing about twenty miles an hour","4-Boy-22","It's drifting into the lot at the drive-in, it went through the fence - it's stopped","4-Boy-22","Out with the ambulance, the driver's door is open, the driver's seat is empty","4-Boy-22","Radio, the little window between the cab and the box is broken out - I can see the crew in the back, both of them, and the patient","Louisville Radio","Are they injured, 4-Boy-22?","4-Boy-22","I'm not opening those doors to find out, start me a supervisor and two more cars"}},
{"r1_d0_air1_fairgrounds_lot","scanner",0,0,21,2,1,{"Air-1","Air-1 to units responding to the fight call at the fairgrounds","Louisville Radio","Go ahead, Air-1","Air-1","I've got the lot lit up, I count thirty to forty people, several on the ground - this is not a fight","Louisville Radio","Air-1, clarify - not a fight?","Air-1","Nobody's throwing punches, the ones standing are down on top of the ones on the ground","Air-1","Units coming in off Crittenden Drive, the crowd is turning toward your sirens - every head in that lot turned at once","4-Boy-17","4-Boy-17 copies, killing my siren","Air-1","Now they're turning toward me, I'm climbing to a thousand feet and holding","Louisville Radio","All units on the fairground detail, stage at the gate on Crittenden Drive, lights only"}},
{"r1_d0_spruce_street_walkback","scanner",0,0,18,3,1,{"Dispatch","Muldraugh Fire, Engine 21, Truck 23, structure fire, 417 Spruce Street - caller reports a man still inside","Engine 21","Engine 21 on scene, one-story frame, smoke showing from the kitchen side, engine 21 will be Spruce Command","Spruce Command","Spruce Command, we've got the occupant out the front door - male, fifties, burns to both hands","Truck 23","Truck 23, Command, he's up off the stretcher, he's walking back toward the house","Spruce Command","Grab him!","Truck 23","We had him, he threw my firefighter off like nothing and went right back in the front door","Spruce Command","All companies, nobody goes back in after him - defensive operation - Exterior lines only","Truck 23","Command, he's standing in the front room, he's looking out the window at us","Spruce Command","I see him, nobody goes in, that's an order - dispatch, start the coroner"}},
{"r1_d0_sarge_second_car_rule","scanner",0,1,0,5,1,{"Knox 20","Knox 20 to all Knox units - listen up","Knox 20","Effective now, nobody goes hands-on with a combative subject alone - you wait for a second car","Knox 20","Gloves on every contact, if you get blood or spit on you, you wash it off before you touch your face - your eyes especially","Knox 11","Knox 11 - Sarge, a second car is twenty minutes out on a good night - this isn't a good night","Knox 20","Then you wait twenty minutes, nobody's getting a medal for this one","Knox 4","Knox 4 - what are we supposed to do in the meantime?","Knox 20","Stay in the car with the doors locked and talk to them on the PA - I'm serious","Knox 9","Knox 9 - Sarge, the ones I've seen tonight don't listen to the PA","Knox 20","I know it - stay in the car anyway"}},
{"r1_d0_knox4_donna_dog","scanner",0,0,19,23,1,{"Knox 4","Knox 4, dispatch, when you get a second, could you 10-21 my house? Tell Donna I'll be late - real late","Dispatch","I'll call her, Knox 4","Dispatch","Knox 4, I got hold of Donna, she says Buckshot dug out under the fence again and it's your turn to go find him","Knox 4","Tell her he always comes home when he gets hungry","Dispatch","I'm not telling her that, you tell her","Knox 4","Knox 4 copies - Buckshot is on his own tonight"}},
{"r1_d0_knox9_other_scanner","scanner",0,0,1,5,1,{"Knox 9","Knox 9 - Linda, you got Louisville up on the other scanner?","Dispatch","I've got it","Knox 9","They've been on emergency traffic for an hour, I can pick it up on my portable, sounds like the whole Second District","Dispatch","I know - keep your mind on our side of the county line","Knox 9","What's the hospital saying?","Dispatch","Hospital hasn't picked up the phone since midnight","Knox 9","Copy - Knox 9 is going to sit in the truck stop lot a minute and drink a coffee","Dispatch","Take ten minutes, you've earned the coffee"}},
{"r1_d0_knox11_pickup_escort","scanner",0,0,21,4,1,{"Knox 11","Knox 11, I'm in pursuit, northbound 31W from the (stepped on)","Dispatch","Units, you doubled, two of you keyed up at once - Knox 11 first, go ahead","Knox 11","Knox 11, pursuit northbound 31W from the Muldraugh line, white pickup, Kentucky plate Tom-Frank-Victor 3-1-8","Dispatch","Copy, Knox 11, unit that was stepped on, go ahead","Knox 15","Knox 15, I'll hold - Knox 11, there's somebody in the bed of that truck - I saw him go by","Knox 11","Affirmative, one in the bed, banging on the back glass - driver's waving me around, I think he's trying to get somebody to a hospital","Dispatch","Knox 11, Knox County Hospital is on diversion","Knox 11","He doesn't care - tell Louisville a pickup is headed their way with a sick one in the bed","Dispatch","Louisville says every emergency room in the city is full - they're asking us not to send anybody","Knox 11","Then I'll just follow him till he figures it out - Knox 11 is terminating the pursuit"}},
{"r1_d0_knox15_coyle_welfare","scanner",0,0,12,18,1,{"Dispatch","Knox 15, welfare check, 88 Coyle Road, daughter in Cincinnati says her father didn't answer the phone this morning, and he always answers","Knox 15","Knox 15, en route - is that Harlan Coyle? He drove my school bus","Dispatch","That's him, eighty-one years old, lives alone, diabetic","Knox 15","Knox 15, 10-23, his truck's here - screen door's shut, front door's standing open behind it","Knox 15","There's blood on the screen, a handprint, on the inside, down low - I want a second unit before I go in","Dispatch","Nearest unit is twenty-five minutes, Knox 15","Knox 15","I'll wait, he's a good man - I'd rather find him with somebody else standing there","Dispatch","Copy, I'll let his daughter know we're on scene - that's all I'll tell her"}},
{"r1_d0_rosewood5_yard_dog","scanner",0,0,13,20,1,{"Dispatch","Rosewood 5, animal complaint, 1200 block of Chestnut, caller says a man is down in the neighbor's yard with the neighbor's dog","Rosewood 5","Rosewood 5 - say again, down with the dog?","Dispatch","Caller says he's on his hands and knees, the dog was barking, and then it quit","Rosewood 5","Copy - en route","Rosewood 5","Rosewood 5, I'm out, I'd like the animal control officer and a second car","Dispatch","Animal control is off till Monday - what have you got?","Rosewood 5","The dog's past helping, the man won't look up at me - run a Dwight Kimsey for me, the name's on the mailbox","Dispatch","Rosewood 5, Dwight Kimsey is the dog's owner, he is the neighbor","Rosewood 5","Then it's his own dog, start that second car - he's getting up"}},
{"r1_d0_trooper435_hurst_home","scanner",0,0,15,22,1,{"Trooper 435","Post 4, 435, traffic stop, US-60 eastbound at Irvington - Kentucky registration Lincoln-Mary-Paul 5-5-2","Post 4","435, go ahead with your traffic","Trooper 435","Driver was weaving, he's not drunk, sweating through his shirt, says something bit him at a rest stop down in Hardin County","Post 4","Does he need EMS?","Trooper 435","He's refusing, says he wants to get home to Brandenburg and lie down","Post 4","The registration comes back clear to a Dale Hurst of Brandenburg","Trooper 435","Copy, I'm going to follow him home, he can barely hold his lane","Trooper 435","Post 4, 435 - Mr. Hurst made it home, his wife met him in the driveway - I'm clear","Post 4","10-4, 435, clear at {time}"}},
{"r1_d0_knox11_herd_running","scanner",0,0,22,4,1,{"Dispatch","Knox 11, livestock in the roadway, Route 1638 at the Otter Creek bridge - several head of cattle","Knox 11","Knox 11 copies - cows, finally, a call they covered at the academy","Knox 11","Knox 11, 10-23, the whole herd's through the fence and out on the blacktop - they're running","Dispatch","Running toward you?","Knox 11","Running away from something back in the pasture, they went right past my car - I never saw cattle move like that","Knox 11","The owner's out here in his undershirt, he wants to go look in the pasture with a flashlight","Dispatch","Advise him not to","Knox 11","He says his cows, his pasture, I'm going with him - I'll keep my portable up","Knox 11","Dispatch, we're back at the truck, we're going to let the cows have the road tonight"}},
{"r1_d0_hospital_security_doors","scanner",0,0,22,4,1,{"Hospital","Knox County, this is hospital security on the county channel - we need deputies at the emergency entrance","Dispatch","Security, how many do you need, and what's the nature?","Hospital","Every one you've got, the waiting room is full of bite injuries, and some of the ones in the back rooms stopped breathing and started getting up","Dispatch","I can give you one unit in fifteen minutes","Hospital","The charge nurse is locking the doors between triage and the back - she wants to know if that's legal","Dispatch","Tell her I'm no lawyer, but I'd lock them too","Hospital","Doors are locked, there's people on both sides of them, send the unit"}},
{"r2_d0_range_check_fire","military",0,0,13,18,2,{"Range Control","All ranges, all ranges, this is Knox Range Control - check fire, I say again, check fire, over","Range 12","Range 12, check fire, roger, range Control, I have tanks downrange in the middle of a qualification table - request reason, over","Range Control","All ranges clear weapons and report cold, units return to garrison immediately, no reason has been given to me, over","Range 12","Roger - be advised, there's a civilian walking across my impact area toward the tower - he came through the fence off the county road, over","Range Control","Say again, a civilian in the impact area, over?","Range 12","Affirmative, man in a work shirt, straight through the target lanes - he walked into a pop-up target, fell, got up and kept coming, over","Range Control","Hold all fire, range safety is en route to pick him up - keep your tower door shut until they arrive, range Control, out"}},
{"r2_d0_no_endex","military",0,0,20,23,2,{"Longbow-3","All Longbow stations, this is Longbow-3 - REDCON-1 at 2300 hours, acknowledge in order, over","Anvil-6","Anvil-6, roger REDCON-1 at 2300, request purpose of the alert, over","Longbow-3","Purpose will be briefed at brigade headquarters - Commanders only, over","Hatchet-6","Hatchet-6, roger, half my platoon sergeants are off post for the weekend - is this a no-notice exercise, over?","Longbow-3","Negative, this is not an exercise - send runners out to the housing areas if the phones don't pick up, over","Crowbar-6","Crowbar-6, roger all - Longbow-3, what's the ENDEX on this one, so I can tell my people something, over?","Longbow-3","No ENDEX has been published - tell them to pack for longer than a weekend - Longbow-3, out"}},
{"r2_d0_ammo_paperwork","military",0,1,22,5,1,{"Anvil-7","Longbow-3, Anvil-7, weapons are drawn, the ammunition supply point won't release live rounds without a signed request from brigade, over","Longbow-3","Anvil-7, the request is being signed now - stand by, over","Anvil-7","I've been standing by since 2200, my soldiers are standing in the motor pool in the dark with empty magazines, over","Longbow-3","Understood, the staff duty officer is driving the paper to the ammo point personally, over","Anvil-7","Tell him to drive faster - MPs on the south road just asked us for help with a man who won't stay down, over","Longbow-3","Say again your last, over","Anvil-7","I say again, the MPs have a man who will not stay down - they have put him down twice, over","Longbow-3","Roger - Anvil-7, you keep that off this net until you're told otherwise - Longbow-3, out"}},
{"r2_d0_gate_ice_cream","military",0,1,18,23,1,{"Gate Two","MP Desk, Gate Two, cars backed up a mile on 31W, mostly dependents with post decals on the windshield, over","MP Desk","Gate Two, the post is closed, dependents with decals come in on foot after inspection, vehicles stay outside, over","Gate Two","Inspection for what, over?","MP Desk","Bites - scratches, anybody running a fever - look at arms and legs, over","Gate Two","Roger, desk, the first car is a major's wife with a sack of groceries and a baby on her hip, over","MP Desk","She walks the baby in and leaves the groceries, no exceptions for rank, over","Gate Two","She's asking if somebody can at least put the ice cream in a freezer, over","MP Desk","Gate Two, clear the net for priority traffic - tell her I'm sorry about the ice cream - out"}},
{"r2_d0_pad_closed","military",0,1,20,4,1,{"Dustoff 1-4","Knox Operations, Dustoff 1-4, inbound to the post hospital with two litter patients from a wreck on Highway 60, over","Knox Operations","Dustoff 1-4, Knox Operations - divert, the hospital pad is closed to all traffic, over","Dustoff 1-4","Say again, the hospital is closed, over?","Knox Operations","I say again, the hospital pad is closed, land at the parade field and hold for a medical team, over","Dustoff 1-4","Knox, my flight medic says one of these patients bit the ambulance driver before we loaded him - he's restrained now - is that related, over?","Knox Operations","Dustoff 1-4, do not discuss patient condition on this frequency - parade field, over","Dustoff 1-4","Roger, parade field, for the record, my crew chief has a bite on his hand from the loading, over","Knox Operations","Copy - keep him in the aircraft after shutdown, nobody gets out to meet you - Knox Operations, out"}},
{"r2_mis_major_dad","military_mistake",0,2,19,23,1,{"Katie","Hello? Is this the Army? This is Katie, my dad left his walkie-talkie on the kitchen table","Longbow-3","Station on this net, this is Longbow-3, this is a military frequency - please put the radio down, over","Katie","Over - is my dad there? He's a major, his name is Dad","Longbow-3","Katie, what's your last name, over?","Katie","Pettigrew - Mom locked all the doors and we're having a sleepover in the hall closet","Longbow-3","Katie, your dad is busy but he's okay - stay in the closet with your mom - leave the radio on the table and don't touch it again, alright? Over","Katie","Okay, over - tell him the closet has the vacuum in it and it smells","Longbow-5","Longbow-3, Longbow-5, I heard all of it - thank you - Longbow-5, out"}},
{"r2_mis_duty_log_laundry","military_mistake",0,1,3,6,1,{"Staff Duty","0200, all quiet. 0215, lights out in the barracks. 0240, private reports noises in the laundry room","Staff Duty","0310, private reports the laundry room noise is a dryer. 0320, private reports the dryer is not plugged in","Longbow-3","Staff duty, Longbow-3, your handset is keyed, everyone on this net is listening to your log, over","Staff Duty","Roger, sir, sorry - Sir, do you want the rest of it, over?","Longbow-3","Yes, what was in the laundry room, over?","Staff Duty","The 0330 entry only says door secured with a mop handle - private Leland wrote it, private Leland isn't at the desk anymore, over","Longbow-3","Roger, two MPs to the laundry room - nobody opens that door alone - Longbow-3, out"}},
{"r2_d0_shoppette_cashier","military",0,0,16,22,2,{"MP 21","Desk, MP 21, on scene at the shoppette by the south housing area - disturbance, one male subject bit the cashier, over","MP Desk","MP 21, say again, bit, over?","MP 21","Bit, on the forearm, drew blood, subject is cuffed in the back of my unit, he's still trying to bite through the cage, over","MP Desk","Is the subject intoxicated, over?","MP 21","Unknown, he doesn't smell of anything, he doesn't answer questions - his eyes don't follow my flashlight, over","MP Desk","Roger - Transport the subject to the hospital for a blood draw - request an ambulance for the cashier, over","MP 21","Cashier refuses the ambulance, she says it's only a bite and she has a shift to finish, over","MP Desk","Tell her she's done for the night, log the time as 1740 - MP Desk, out"}},
{"r7_mil_armory_21_opens","military",0,1,18,23,1,{"Boone Main","Armory 21, this is Boone Main at Frankfort, you are activated as of tonight - open the armory and report your strength, over","Armory 21","Boone Main, Armory 21, I've got the doors open and I've got eleven soldiers stood in the drill hall, over","Boone Main","Armory 21, your authorized strength is a hundred and forty, over","Armory 21","I know what it is, it's a Friday night in July, Boone Main, half my company drives a truck for a living and the phones are out, over","Boone Main","Armory 21, send runners to the housing streets and the two plants - anybody who shows up gets fed and gets a bunk, over","Armory 21","Roger - Boone Main, what am I telling them we're doing, over?","Boone Main","Tell them state active duty, in state, and that you'll know more in the morning, over","Armory 21","Will I know more in the morning, over?","Boone Main","No, armory 21, Boone Main, out"}},
{"r7_nights_rollcall_short","scanner",0,0,22,23,2,{"Knox 20","Knox 20 to all night units - roll call, I got four cars for the whole county and two of them are on fumes, so listen up","Knox 20","No single unit entries on anything where somebody's fighting, you wait for a second car - I don't care how long you sit on the road","Knox 22","Knox 22, Sarge - second car from where? Kidwell's the only other body out here","Knox 20","Then you two are married tonight - Knox 24, you copy that?","Knox 24","Knox 24 copies - married, my wife's gonna be tickled to hear it","Knox 20","Gloves on, sleeves down, nobody puts their hands near a mouth - dispatch, show night shift 10-8 at {time}","Dispatch","Copy, all units 10-8, and boys, I got eleven calls holding over from day shift - eleven, I'll go in the order they came in"}},
{"r7_nights_welfare_barbee_road","scanner",0,1,23,4,1,{"Dispatch","Knox 22, welfare check, 1140 Barbee Road, daughter in Ohio says her daddy ain't answered the phone since Thursday","Knox 22","Knox 22, en route - that's the white house with the propane tank out front, ain't it?","Dispatch","That's the one, she says he's eighty-one and he don't drive no more, so his car ought to be sitting right there","Knox 22","Knox 22 on scene - car's here - TV's going in the front room, I can see the light jumping on the ceiling","Knox 22","Dispatch, the screen door's latched from the inside, I'm going around the back - start somebody my way, would you","Dispatch","Ain't nobody to start, 22 - Knox 24's on a wreck at the Otter Creek ramp","Knox 22","Copy, going in anyway - if I don't come back up in five minutes, call the sheriff at his house and tell him where I'm at"}},
{"r7_nights_open_line_payphone","scanner",0,2,0,3,2,{"Dispatch","Knox 24, open line to 911 off the payphone at the Dixie Mart - no voice, line's just open - been open four minutes","Knox 24","Knox 24, show me that way - what do you hear on it?","Dispatch","Breathing - somebody's there, I've asked twelve times can they tap the receiver for me and I get nothing back","Knox 24","Keep it open, that's the phone on the side wall, ain't it - no light over that one","Dispatch","Side wall, yes - hold on, 24, I got a sound","Knox 24","What kind of sound?","Dispatch","Like the receiver knocking the box, over and over, same beat - like somebody let go of it and it's just swinging there","Knox 24","Knox 24 on scene - Receiver's hanging, dispatch, there ain't a soul at this phone, and there's one shoe out in the middle of the lot"}},
{"r7_nights_legion_hall_fight","scanner",0,1,22,2,2,{"Dispatch","Knox 22 and Knox 24, fight in progress, the Legion hall on Ashland Avenue - caller says four or five men and one of them is biting","Knox 22","Knox 22 en route from Muldraugh, four minutes. 24, you closer than that?","Knox 24","Knox 24, two minutes, I ain't going through that door alone, Sarge said","Knox 20","Knox 20's coming too, nobody goes in till all three of us are stood on that sidewalk together","Knox 24","Knox 24 on scene, one man down in the doorway and about twenty people out in the lot, and every one of them is hollering at me","Knox 22","22 on scene, dispatch, I need the ambulance now, the man in the doorway's bleeding out of his neck","Dispatch","EMS is on a call in Rosewood, I'll send the first one that clears - it may be a while, 22","Knox 22","Then tell the Legion to bring me every clean bar towel in that building - go on, tell 'em, I mean right now"}},
{"r7_nights_dead_spot_relay","scanner",0,3,0,5,1,{"Dispatch","Knox 26, Knox 26, Knox County - radio check","Dispatch","Knox 26, Knox County - do you copy?","Knox 22","Dispatch, Knox 22, he's down in the bottoms off Echo Creek Road, nothing gets out of that hole - want me to relay?","Dispatch","Please, tell him his call is out at the Kelso place and to advise when he's 10-23","Knox 22","Knox 26, Knox 22 relaying for county, your call is the Kelso place, advise on arrival","Knox 26","Knox 22, Knox 26, I got you real faint, copy the Kelso place - tell 'em I'll holler when I climb back up to the road","Knox 22","Dispatch, 26 copies, he's going in, and he'll come back up to the road to talk to us","Dispatch","Copy that - Knox 22, don't you lose him, you're the only reason I know where he's at"}},
{"r7_nights_bar_wont_close","scanner",0,1,23,3,1,{"Dispatch","Knox 24, that place out on Rosewood Road with the horseshoe sign won't close - neighbors are calling about the noise","Knox 24","Knox 24 en route, last call was two hours ago","Knox 24","Knox 24, I'm 10-23, there's thirty people in here and the bartender tells me not one of them wants to go home","Dispatch","You need another unit?","Knox 24","No, dispatch, I asked a fella why he wasn't going home and he said his house is on Pruitt Lane - that's all he said to me","Dispatch","Pruitt Lane's where that call was Friday","Knox 24","Yeah, I'm gonna let 'em keep the lights on, I'll sit in the lot till they run out of beer or run out of steam"}},
{"exp_fire_rollcall","scanner",1,7,0,23,1,{"Engine Two","We're short on the volunteer list - have you heard from anybody else?","Control","Not since the last time you asked","Engine Two","I'm not complaining about you - just checking","Control","I know, everybody wants to check one more time","Engine Two","Leave the blank spaces, don't cross the names off","Control","Wasn't going to, we don't know anything yet","Engine Two","Right, that's all I wanted to say","Control","I'll keep the list in front of me"}},
{"more_radio_night_footsteps","caller_story_horror",1,14,21,5,1,{"Carl","I heard somebody walking upstairs after everybody came down","Carl","Nobody believed me because I kept saying somebody","Carl","We knew, June, I just couldn't say it - kept saying 'somebody'","June","Did you get out?","Carl","We're out, nobody went up there","Carl","Nearly did, had my foot on the bottom stair - then my wife grabbed me","Carl","Pulled so hard she tore my shirt, thank God she did","Carl","My father would've called that cowardly","June","Carl, you both got out, I'm glad she stopped you","Carl","Me too, I should tell her that, been talking about the shirt like an idiot"}},
{"more_radio_light_under_door","caller_story_horror",1,10,21,5,1,{"Unknown","The light under the door kept moving","Unknown","I thought somebody was walking past with a flashlight","Unknown","I nearly shouted hello, got as far as the H and swallowed it","June","What was it?","Unknown","A curtain blowing in front of a lamp, nothing behind it","June","You checked?","Unknown","In the morning, not in the dark","Unknown","I was angry when I found out, I'd spent hours scared of a curtain","Unknown","A fucking curtain - sorry, I'm still mad about it","June","I would've been scared too, you didn't know"}},
{"more_radio_guard_birthday","military",1,14,0,23,1,{"Trainee","It's my birthday, Sergeant","Sergeant","Congratulations - keep your eyes up","Trainee","I'm twenty","Sergeant","Twenty? Jesus, thought you were older","Trainee","My mom usually calls first thing, before I'm even up","Sergeant","I know","Trainee","Not asking to leave or anything, I just-- never mind","Sergeant","Didn't take it as one","Trainee","Thanks, Sergeant","Sergeant","Happy birthday, kid, I'll see what we've got for supper"}},
}
